import subprocess
from pathlib import Path

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("filing-prep")


@mcp.tool()
def run_pdf_integrity_check(document_path: str, timeout_seconds: int = 60) -> dict:
    resolved_document_path = Path(document_path).expanduser().resolve()
    if not resolved_document_path.is_file():
        return {"document": str(resolved_document_path), "valid": False, "error": "Document not found"}
    qpdf_command_arguments = ["qpdf", "--check", str(resolved_document_path)]
    try:
        completed_check_process = subprocess.run(
            qpdf_command_arguments,
            capture_output=True,
            text=True,
            timeout=timeout_seconds,
        )
    except subprocess.TimeoutExpired:
        return {"document": str(resolved_document_path), "valid": False, "error": "Integrity check timed out"}
    combined_checker_output_lines = (completed_check_process.stdout + completed_check_process.stderr).splitlines()
    warning_lines_from_checker = [line for line in combined_checker_output_lines if "WARNING" in line.upper()]
    document_passed_integrity_check = completed_check_process.returncode == 0
    return {
        "document": str(resolved_document_path),
        "valid": document_passed_integrity_check,
        "exit_code": completed_check_process.returncode,
        "warnings": warning_lines_from_checker,
        "output": combined_checker_output_lines[-50:],
    }

import re
import shutil
from pathlib import Path

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("records-management")

ACTIVE_ROOT = Path("/srv/legal/active_matters")
ARCHIVE_ROOT = Path("/srv/legal/records_archive")
_MATTER_PATTERN = re.compile(r"^\d{4}-[A-Z]{2,5}-\d{3,6}$")


def _unique_destination(base: Path) -> Path:
    if not base.exists():
        return base
    counter = 1
    while True:
        candidate = base.with_name(f"{base.name}_{counter}")
        if not candidate.exists():
            return candidate
        counter += 1


def _count_files(folder: Path) -> int:
    return sum(1 for p in folder.rglob("*") if p.is_file())


@mcp.tool()
def archive_closed_matter_files(matter_id: str, closed_year: int, dry_run: bool = False) -> dict:
    result = {"matter_id": matter_id, "closed_year": closed_year, "dry_run": dry_run, "moved": False}
    if not _MATTER_PATTERN.match(matter_id):
        result["error"] = "Matter ID is not in the expected format"
        return result
    if closed_year < 1950 or closed_year > 2100:
        result["error"] = "Closed year is out of range"
        return result
    source = ACTIVE_ROOT / matter_id
    if not source.is_dir():
        result["error"] = f"No active folder found at {source}"
        return result
    year_folder = ARCHIVE_ROOT / str(closed_year)
    destination = _unique_destination(year_folder / matter_id)
    result["source"] = str(source)
    result["destination"] = str(destination)
    result["file_count"] = _count_files(source)
    result["renamed_for_collision"] = destination.name != matter_id
    if dry_run:
        return result
    year_folder.mkdir(parents=True, exist_ok=True)
    try:
        shutil.move(str(source), str(destination))
    except (OSError, shutil.Error) as exc:
        result["error"] = f"Move failed: {exc}"
        return result
    result["moved"] = True
    result["archived_file_count"] = _count_files(destination)
    return result
